/* Sourced battles and campaigns, anchored to documented years and approximate places. */
(function(scope){
'use strict';
let data={wars:[],sources:{}},ctx={},selected=null;
const $=id=>document.getElementById(id),esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const yr=n=>n<0?'前'+(-n)+'年':n+'年',range=w=>w.startYear===w.endYear?yr(w.startYear):yr(w.startYear)+'—'+yr(w.endYear);
const active=y=>data.wars.filter(w=>w.startYear<=y&&w.endYear>=y);
const activePlaces=(w,y)=>w.locations.filter(p=>y>=(p.fromYear??w.startYear)&&y<=(p.toYear??w.endYear));
const placeRange=(w,p)=>range({startYear:p.fromYear??w.startYear,endYear:p.toYear??w.endYear});
const phaseLabel=p=>({'origin':'起兵','mobilization':'集结','political-center':'政治中心','political-event':'政治事件','treaty':'议约','diplomacy':'纳土／移交','siege':'围城','theatre':'战区','ending-region':'终局区域','ending':'终局','battle':'战役','event':'战事节点'}[p.phaseType]||'战事地点');
const phasePath=p=>['origin','mobilization'].includes(p.phaseType)?'M-4 6V-6L5-3-4 0':['political-center','political-event'].includes(p.phaseType)?'M-6-2 0-6 6-2M-4-1V5M0-1V5M4-1V5M-6 6H6':p.phaseType==='theatre'?'M-6 0A6 6 0 1 0 6 0A6 6 0 1 0-6 0':['treaty','diplomacy'].includes(p.phaseType)?'M-4-6H4V6H-4ZM-2-2H2M-2 2H2':'M-5-5 5 5M-5 5 5-5M-6-2-2-6M2 6 6 2M-6 2-2 6M2-6 6-2';
const enabled=()=>!$('warToggle')||$('warToggle').checked;
function key(y){return (enabled()?active(y).map(w=>w.id+':'+activePlaces(w,y).map(p=>p.label).join(',')).join('|'):'off')+'|'+(selected||'');}
function related(event){const list=data.wars.filter(w=>(w.eventIds||[]).includes(event.id));return list.filter(w=>!(w.overlapsWarIds||[]).some(id=>list.some(x=>x.id===id)));}
function cardLinks(event){return related(event).map(w=>'<button type="button" class="battle-place-chip" data-war-id="'+esc(w.id)+'" aria-label="'+esc(w.title+'：查看战事地点、时间与依据')+'"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s7-8 7-13a7 7 0 0 0-14 0c0 5 7 13 7 13Z"/><circle cx="12" cy="8" r="2"/></svg>'+esc(activePlaces(w,event.year).map(p=>p.label).slice(0,2).join(' · ')||'战事地点与分期')+'<span>'+esc(range(w))+'</span></button>').join('');}
function sourceLinks(w){return (w.sourceIds||[]).map(id=>data.sources[id]).filter(Boolean).map(s=>'<a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.title)+' ↗</a>').join('');}
function locate(w,y=w.startYear){ctx.stop?.();selected=w.id;if($('warToggle'))$('warToggle').checked=true;for(const id of ['warDialog','warCatalogue','eventStoryDialog','libraryDialog'])if($(id)?.open)$(id).close();ctx.setYear(y);}
function open(id){const w=data.wars.find(w=>w.id===id);if(!w)return;ctx.stop?.();if($('warCatalogue')?.open)$('warCatalogue').close();const d=$('warDialog');d.innerHTML='<button class="close" aria-label="关闭战事详情">×</button><div class="war-detail-time">'+esc(range(w))+'</div><h2>'+esc(w.title)+'</h2><div class="war-parties">'+w.parties.map(p=>'<span>'+esc(p)+'</span>').join(w.scopeType==='campaign-series'?'<i>·</i>':'<i>⚔</i>')+'</div><p>'+esc(w.outcome)+'</p>'+(w.whyImportant?'<p class="war-impact">'+esc(w.whyImportant)+'</p>':'')+'<div class="war-location-list">'+w.locations.map(p=>'<div><b>'+esc(p.label)+'</b><span>'+esc(phaseLabel(p)+' · '+placeRange(w,p))+'</span><small>'+esc(p.dateNote||p.role||'地点参照')+'</small></div>').join('')+'</div><p class="war-precision">'+esc(w.locationNote||'标记为战事区域的近似锚点，不是精确战场边界。')+'</p>'+(w.dateNote?'<p class="war-precision">'+esc(w.dateNote)+'</p>':'')+'<div class="war-detail-actions"><button data-war-locate="'+w.startYear+'">↗ '+esc(w.startDateLabel||yr(w.startYear))+'</button>'+(w.endYear>w.startYear?'<button data-war-locate="'+w.endYear+'">↗ '+esc(w.endDateLabel||yr(w.endYear))+'</button>':'')+'</div><details class="war-sources"><summary>史料与出处 · '+w.sourceIds.length+'</summary>'+sourceLinks(w)+'</details>';d.querySelector('.close').onclick=()=>d.close();d.querySelectorAll('[data-war-locate]').forEach(b=>b.onclick=()=>locate(w,+b.dataset.warLocate));if(!d.open)d.showModal();}
function catalogue(){ctx.stop?.();const d=$('warCatalogue');d.innerHTML='<button class="close" aria-label="关闭战事图谱">×</button><div class="eyebrow">BATTLES &amp; CAMPAIGNS</div><h2>战事图谱</h2><div class="war-catalogue-tools"><input id="warSearch" type="search" placeholder="查战争、地点或交战双方" aria-label="搜索战事"><label><input id="warOnlyCurrent" type="checkbox">只看本年</label></div><div id="warCatalogueList"></div><p class="war-precision">日期按来源所能支持的精度显示。地图标记是区域锚点，不复原战场边界或行军路线。</p>';d.querySelector('.close').onclick=()=>d.close();const render=()=>{const search=$('warSearch').value.trim(),current=$('warOnlyCurrent').checked,found=data.wars.filter(w=>(!current||w.startYear<=ctx.getYear()&&w.endYear>=ctx.getYear())&&(!search||[w.title,w.location,...w.parties].join(' ').includes(search)));$('warCatalogueList').innerHTML=found.map(w=>'<button class="war-catalogue-row" data-war-id="'+esc(w.id)+'"><time>'+esc(range(w))+'</time><span><strong>'+esc(w.title)+'</strong><small>'+esc(w.location)+'</small></span><i>↗</i></button>').join('')||'<p class="no-result">这个范围没有已整理的战事。</p>';};$('warSearch').oninput=render;$('warOnlyCurrent').onchange=render;render();d.showModal();}
function sync(y){const wars=active(y),summary=$('warYearSummary');if(summary){summary.hidden=!wars.length;summary.textContent=wars.length>2?'⚔ 本年 '+wars.length+' 组战事':'⚔ '+wars.map(w=>w.title).join(' · ');summary.title=wars.map(w=>range(w)+' · '+w.title).join('；');}}
function init(input,context){data=input;ctx=context;for(const [id,label]of [['warDialog','战事时间与地点'],['warCatalogue','战事图谱']])if(!$(id)){const d=document.createElement('dialog');d.id=id;d.className='war-dialog';d.setAttribute('aria-label',label);document.body.append(d);}$('warCatalogueBtn').onclick=catalogue;if($('warYearSummary'))$('warYearSummary').onclick=catalogue;document.addEventListener('click',e=>{const b=e.target.closest('[data-war-id]');if(b){e.stopPropagation();open(b.dataset.warId);}});}
function draw(root,project,y,options){sync(y);if(!enabled())return;const layer=root.append('g').attr('class','war-map-layer'),k=Number(root.style('--city-zoom'))||1;const candidates=active(y).sort((a,b)=>(a.id===selected?-1:b.id===selected?1:(b.priority||0)-(a.priority||0)));let count=0;for(const w of candidates){for(const [i,place]of activePlaces(w,y).entries()){if((w.overlapsWarIds||[]).some(id=>candidates.some(child=>child.id===id&&activePlaces(child,y).some(cp=>Math.hypot(cp.coordinates[0]-place.coordinates[0],cp.coordinates[1]-place.coordinates[1])<.4))))continue;if(count>=8)break;const p=project(place.coordinates);if(!p||!p.every(Number.isFinite)||p[0]<8||p[0]>options.width-8||p[1]<10||p[1]>options.height-35)continue;count++;const g=layer.append('g').attr('class','war-marker'+(w.id===selected?' war-selected':'')).attr('transform','translate('+p+')').attr('role','button').attr('tabindex',0).attr('data-battle-id',w.id).attr('aria-label',w.title+'，'+place.label+'，'+phaseLabel(place)+'，'+placeRange(w,place)+'，查看依据').on('click',e=>{e.stopPropagation();open(w.id);}).on('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();open(w.id);}});const inner=g.append('g').attr('class','war-symbol').attr('transform','scale('+1/k+')');inner.append('circle').attr('class','war-region-halo').attr('r',17);inner.append('circle').attr('class','war-pin-bg').attr('r',9.5);inner.append('path').attr('class','war-swords').attr('d',phasePath(place));inner.append('title').text(w.title+' · '+range(w)+'\n'+place.label+' · '+phaseLabel(place)+' · '+placeRange(w,place)+'\n'+(place.dateNote||place.role||'区域参照')+'\n'+w.locationNote);if(i>0)continue;const label=w.title.length>12?w.title.slice(0,11)+'…':w.title,date=placeRange(w,place),width=Math.max(label.length*10,date.length*6)+12;let offset=null;for(const [dx,dy]of [[15,-16],[15,22],[-width-15,-16],[-width-15,22],[15,-36]]){const box=[p[0]+dx-4,p[1]+dy-12,p[0]+dx+width,p[1]+dy+18];if(box[0]<8||box[2]>options.width-8||box[1]<8||box[3]>options.height-40||options.reserved.some(b=>b[0]<box[2]&&b[2]>box[0]&&b[1]<box[3]&&b[3]>box[1]))continue;offset=[dx,dy];options.reserved.push(box);break;}if(!offset)continue;inner.insert('rect',':first-child').attr('x',Math.min(-18,offset[0]-5)).attr('y',Math.min(-18,offset[1]-13)).attr('width',Math.max(18,offset[0]+width)-Math.min(-18,offset[0]-5)).attr('height',Math.max(18,offset[1]+19)-Math.min(-18,offset[1]-13)).attr('fill','transparent').attr('pointer-events','all');inner.append('rect').attr('class','war-label-bg').attr('x',offset[0]-4).attr('y',offset[1]-12).attr('width',width).attr('height',31).attr('rx',4);inner.append('text').attr('class','war-map-title').attr('x',offset[0]+2).attr('y',offset[1]).text(label);inner.append('text').attr('class','war-map-date').attr('x',offset[0]+2).attr('y',offset[1]+12).text(date);}}
}
scope.WarContext={init,key,active,activePlaces,related,cardLinks,draw,open,catalogue,sync};if(typeof module!=='undefined')module.exports=scope.WarContext;
})(globalThis);
